	private static String lexical(long id) {
		return "urn:test:admission:" + id;
	}

	/** Fresh source objects are kept by intentional test consumers to remove GC as a policy confounder. */
	private static final class Fixture implements AutoCloseable {
		final LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(BUDGET, BUDGET);
		final LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
		final NativeDirectValueMemo memo = new NativeDirectValueMemo(ledger);
		final FixedRevision revision = new FixedRevision();
		final List<Value> consumerRoots = new ArrayList<>();
		long sourceCalls;

		Value unique(int count) {
			Value last = null;
			for (int index = 1; index <= count; index++) {
				last = resolve(index);
			}
			return last;
		}

		Value resolve(long id) {
			Value value = memo.find(id, MASK);
			if (value == null) {
				sourceCalls++;
				value = new LmdbIRI(revision, id);
				memo.remember(id, MASK, value);
			}
			consumerRoots.add(value);
			assertThat(((LmdbValue) value).getInternalID()).isEqualTo(id);
			assertThat(value.stringValue()).isEqualTo(lexical(id));
			return value;
		}

		@Override
		public void close() {
			try {
				memo.close();
			} finally {
				Reference.reachabilityFence(consumerRoots);
				consumerRoots.clear();
				ledger.close();
			}
			assertThat(revision.initializations).isEqualTo(sourceCalls);
			assertThat(ledger.usedBytes()).isZero();
			assertThat(manager.usedBytes()).isZero();
		}
	}

	/** Three hot requests followed by one conflicting request; the pair collides through the maximum capacity. */
	private static final class GrowthTrace {
		final long first;
		final long second;
		final long hot;

		GrowthTrace() {
			long[] seen = new long[NativeDirectValueMemo.MAX_CAPACITY];
			long firstCandidate = 0L;
			long secondCandidate = 0L;
			for (long id = 1L; id <= 4L * NativeDirectValueMemo.MAX_CAPACITY; id++) {
				int slot = NativeDirectValueMemo.slot(id, MASK, NativeDirectValueMemo.MAX_CAPACITY);
				if (seen[slot] != 0L) {
					firstCandidate = seen[slot];
					secondCandidate = id;
					break;
				}
				seen[slot] = id;
			}
			if (firstCandidate == 0L) {
				throw new AssertionError("Could not find deterministic conflicting trace keys");
			}
			first = firstCandidate;
			second = secondCandidate;
			long candidate = 1L;
			while (NativeDirectValueMemo.slot(candidate, MASK, 4096) == NativeDirectValueMemo.slot(first, MASK, 4096)) {
				candidate++;
			}
			hot = candidate;
		}

		void run(Fixture fixture, int offset, int count) {
			for (int index = offset; index < offset + count; index++) {
				long id = (index & 3) != 3 ? hot : ((index >>> 2) & 1) == 0 ? first : second;
				fixture.resolve(id);
			}
		}
	}

	private static final class FixedRevision extends ValueStoreRevision.Base {
		long initializations;

		@Override
		public long getRevisionId() {
			return 77L;
		}

		@Override
		public ValueStore getValueStore() {
			return null;
		}

		@Override
		public boolean resolveValue(long id, LmdbValue value) {
			initializations++;
			value.setFromInitializedValue(new LmdbIRI(this, lexical(id), id));
			return true;
		}
	}
